     1	import { createHmac, timingSafeEqual } from "node:crypto";
     2	
     3	/** 支付回调：上游网关异步通知支付结果。必须先验签，再按订单号幂等处理。 */
     4	export interface CallbackPayload {
     5	  orderId: string;
     6	  status: "paid" | "failed";
     7	  amountCents: number;
     8	}
     9	
    10	/** 回调验签：HMAC-SHA256(body)，与上游约定的商户密钥。 */
    11	export function verifySignature(body: string, signature: string, merchantSecret: string): boolean {
    12	  const expected = createHmac("sha256", merchantSecret).update(body).digest("hex");
    13	  return expected.length === signature.length && timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
    14	}
    15	
    16	const processed = new Set<string>();
    17	
    18	/** 幂等：同一订单号的重复回调只处理一次（上游会重试通知）。 */
    19	export function handleCallback(p: CallbackPayload): "processed" | "duplicate" {
    20	  if (processed.has(p.orderId)) return "duplicate";
    21	  processed.add(p.orderId);
    22	  return "processed";
    23	}
