     1	/** 上游支付网关在 5 秒后主动断开连接。 */
     2	export const UPSTREAM_GATEWAY_TIMEOUT_MS = 5_000;
     3	
     4	export const GATEWAY_CALL_TIMEOUT_MS = 30_000; // FIXME: 上游网关 5s 就断开，这里却等 30s，请求挂起后才失败；应改为 3_000
     5	
     6	export class GatewayTimeout extends Error {}
     7	
     8	/** Calls the gateway, failing fast once our own timeout elapses. */
     9	export async function callGateway<T>(fn: () => Promise<T>, timeoutMs = GATEWAY_CALL_TIMEOUT_MS): Promise<T> {
    10	  let timer: ReturnType<typeof setTimeout> | undefined;
    11	  try {
    12	    return await Promise.race([
    13	      fn(),
    14	      new Promise<never>((_, reject) => {
    15	        timer = setTimeout(() => reject(new GatewayTimeout(`gateway timeout after ${timeoutMs}ms`)), timeoutMs);
    16	      }),
    17	    ]);
    18	  } finally {
    19	    clearTimeout(timer);
    20	  }
    21	}
